const decodeCells = (encodedCells: string) =>
  encodedCells
    ? encodedCells
        .match(/.{1,4}/g)!
        .map((cell) => [Number.parseInt(cell.slice(0, 2), 36), Number.parseInt(cell.slice(2, 4), 36)] as const)
    : [];

